$\left(- 9 x - 4\right) \left(6 x + 9\right)= \left(9 - 6 x\right) \left(6 x + 9\right)$\\
$\left(- 9 x - 4\right) \left(6 x + 9\right) - \left(9 - 6 x\right) \left(6 x + 9\right)=0$\\
$\left(- 3 x - 13\right) \left(6 x + 9\right)= 0$\\
$\begin{cases}
6 x + 9 = 0 \\
                            - 3x - 13 = 0
\end{cases}$\\
$\left[ \begin{array}{l}
                            x=- \dfrac{3}{2} \\
                            x=- \dfrac{13}{3}  
                            \end{array} \right.$
}\end{ex}

\begin{ex}%[9D2V1-3]
Giải phương trình $- \dfrac{8 x}{x + 1} - \dfrac{2}{x - 1}= \dfrac{- x - 2}{x^{2} - 1}$
\loigiai{
Điều kiện xác định: $x \ne \pm 1$.\\
$- 8 x \left(x - 1\right)-2(x+1)=- x - 2$\\
$- 8 x^{2} + 6 x - 2=- x - 2$\\
$- 8 x^{2} + 7 x=0$\\
$x \left(7 - 8 x\right)=0$\\
$\left[ \begin{array}{l}
x = 0 \\
x = \dfrac{7}{8}
\end{array} \right.$\\
Kiểm tra điều kiện và kết luận nghiệm của phương trình
}\end{ex}

\begin{ex}%[9D2V1-3]
Giải phương trình $\left(2 - 9 x\right) \left(- 6 x - 1\right)= \left(- 6 x - 1\right) \left(7 x - 1\right)$
\loigiai{
$\left(2 - 9 x\right) \left(- 6 x - 1\right)= \left(- 6 x - 1\right) \left(7 x - 1\right)$\\
$\left(2 - 9 x\right) \left(- 6 x - 1\right) - \left(- 6 x - 1\right) \left(7 x - 1\right)=0$\\
$\left(3 - 16 x\right) \left(- 6 x - 1\right)= 0$\\
$\begin{cases}
-6x - 1 = 0 \\
                            3 - 16x = 0
\end{cases}$\\
$\left[ \begin{array}{l}
                            x=- \dfrac{1}{6} \\
                            x=\dfrac{3}{16}  
                            \end{array} \right.$
}\end{ex}

\begin{ex}%[9D2V1-3]
Giải phương trình $\left(6 - 2 x\right) \left(- 2 x - 6\right)= \left(- 10 x - 6\right) \left(- 2 x - 6\right)$
\loigiai{
$\left(6 - 2 x\right) \left(- 2 x - 6\right)= \left(- 10 x - 6\right) \left(- 2 x - 6\right)$\\
$\left(6 - 2 x\right) \left(- 2 x - 6\right) - \left(- 10 x - 6\right) \left(- 2 x - 6\right)=0$\\
$\left(- 2 x - 6\right) \left(8 x + 12\right)= 0$\\
$\begin{cases}
-2x - 6 = 0 \\
                            8 x + 12 = 0
\end{cases}$\\
$\left[ \begin{array}{l}
                            x=-3 \\
                            x=- \dfrac{3}{2}  
                            \end{array} \right.$
}\end{ex}
